order_id = #{orderId}, product_id = #{productId}, quantity = #{quantity}, unit_price = #{unitPrice}, note = #{note,jdbcType=VARCHAR}, status = #{status}, prepared_by = #{preparedBy,jdbcType=BIGINT}, started_at = #{startedAt,jdbcType=TIMESTAMP}, ready_at = #{readyAt,jdbcType=TIMESTAMP}, served_by = #{servedBy,jdbcType=BIGINT}, served_at = #{servedAt,jdbcType=TIMESTAMP}, cancelled_by = #{cancelledBy,jdbcType=BIGINT}, cancelled_at = #{cancelledAt,jdbcType=TIMESTAMP}, cancel_reason = #{cancelReason,jdbcType=VARCHAR}, version = version + 1,
